str_replace_editor create /testbed/test_final.py --file_text 'import numpy as np
from astropy.nddata import NDDataRef

print("=== Testing the fix for NDDataRef mask propagation issue ===")
print("PR: In v5.3, NDDataRef mask propagation fails when one of the operand does not have a mask")
print()

array = np.array([[0, 1, 0], [1, 0, 1], [0, 1, 0]])
mask = np.array([[0, 1, 64], [8, 0, 1], [2, 1, 0]])

nref_nomask = NDDataRef(array)
nref_mask = NDDataRef(array, mask=mask)

print("1. Test from PR: multiply mask by constant with np.bitwise_or")
print("   Expected: Should work (return the mask), not raise TypeError")
try:
    result = nref_mask.multiply(1., handle_mask=np.bitwise_or).mask
    print(f"   ✓ Success: Got mask of shape {result.shape}")
except TypeError as e:
    print(f"   ✗ Error: {e}")

print("\n2. Test: multiply mask by no mask NDData with np.bitwise_or")
print("   Expected: Should work (return the mask)")
try:
    result = nref_mask.multiply(nref_nomask, handle_mask=np.bitwise_or).mask
    print(f"   ✓ Success: Got mask of shape {result.shape}")
except TypeError as e:
    print(f"   ✗ Error: {e}")

print("\n3. Test: multiply no mask by mask with np.bitwise_or")
print("   Expected: Should work (return the mask)")
try:
    result = nref_nomask.multiply(nref_mask, handle_mask=np.bitwise_or).mask
    print(f"   ✓ Success: Got mask of shape {result.shape}")
except TypeError as e:
    print(f"   ✗ Error: {e}")

print("\n4. Test: multiply mask by constant with np.logical_or (default)")
print("   Expected: Should work (return the mask), not return array with None values")
try:
    result = nref_mask.multiply(1., handle_mask=np.logical_or).mask
    if result is not None and hasattr(result, '"'"'dtype'"'"') and result.dtype == object:
        print(f"   ✗ Error: Got object dtype array with None values")
    else:
        print(f"   ✓ Success: Got mask of shape {result.shape}")
except Exception as e:
    print(f"   ✗ Error: {e}")

print("\n5. Test: Custom function that handles None")
def custom_func(mask1, mask2):
    if mask1 is None and mask2 is None:
        return None
    elif mask1 is None:
        return mask2
    elif mask2 is None:
        return mask1
    else:
        return mask1 | mask2

try:
    result = nref_mask.multiply(1., handle_mask=custom_func).mask
    print(f"   ✓ Success: Custom function was called and returned mask")
except Exception as e:
    print(f"   ✗ Error: {e}")

print("\n6. Test: Both masks exist, np.bitwise_or should combine them")
mask2 = np.array([[1, 0, 1], [0, 1, 0], [1, 0, 1]])
nref_mask2 = NDDataRef(array, mask=mask2)
try:
    result = nref_mask.multiply(nref_mask2, handle_mask=np.bitwise_or).mask
    expected = mask | mask2
    if np.array_equal(result, expected):
        print(f"   ✓ Success: Masks combined correctly with bitwise_or")
    else:
        print(f"   ✗ Error: Masks not combined correctly")
except Exception as e:
    print(f"   ✗ Error: {e}")

print("\n=== All tests completed ===")'

